'use client'
import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { savePayoutAccount } from '@/lib/paystack/actions'
export default function PayoutAccount({banks,mode,saved}:{banks:{code:string;name:string}[];mode:string;saved:{account_name:string;bank_name:string;last_four:string}|null}){
  const router=useRouter(),[bank,setBank]=useState(''),[account,setAccount]=useState(''),[confirmed,setConfirmed]=useState(false),[busy,setBusy]=useState(false),[notice,setNotice]=useState('')
  async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setNotice('');try{const result=await savePayoutAccount({bank,account,confirmed});setNotice('error'in result?(result.error??'Payout account could not be saved.'):`Paystack resolved and saved the account for ${result.accountName}.`);if(!('error'in result)){setAccount('');setConfirmed(false);router.refresh()}}catch{setNotice('Account setup could not be confirmed. Refresh and check before retrying.')}finally{setBusy(false)}}
  return <section className="buyer-panel buyer-stack"><p className="buyer-notice">{mode.toUpperCase()} environment. {mode==='test'?'Use only Paystack’s documented test bank details. No real money will be transferred.':'Approved transfers will be sent to the resolved bank account.'} You must have signed in within the last 10 minutes to change this account.</p>{saved&&<p>Current beneficiary: <strong>{saved.account_name}</strong>, {saved.bank_name} ····{saved.last_four}.</p>}<form className="buyer-form" onSubmit={e=>void submit(e)}><label>Bank<select className="buyer-input" value={bank} onChange={e=>setBank(e.target.value)} required disabled={busy}><option value="">Select bank</option>{banks.map((bank,i)=><option value={bank.code} key={`${bank.code}-${i}`}>{bank.name}</option>)}</select></label><label>Account number<input className="buyer-input" value={account} onChange={e=>setAccount(e.target.value.replace(/\D/g,''))} inputMode="numeric" pattern="[0-9]{10}" maxLength={10} required disabled={busy} autoComplete="off"/></label><label className="by-check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)} required disabled={busy}/><span>I am authorized to receive store earnings into this account. Paystack will resolve its registered name. I will check the saved beneficiary before requesting a payout. No card PIN, bank password or OTP is needed here.</span></label><button className="buyer-btn is-primary" disabled={busy||!confirmed}>{busy?'Resolving account…':'Resolve and save payout account'}</button></form>{notice&&<p role="status" className="buyer-notice">{notice}</p>}<p className="buyer-help">The full account number is sent securely to Paystack for resolution. CampusMart stores the recipient reference, resolved name, bank and last four digits for this setup. <Link href="/privacy">Privacy details</Link></p><Link className="buyer-btn" href="/vendor/earnings">Back to earnings</Link></section>
}
